fn prefix_sum(k: i8) -> i8 {
    if k == 0 {
        0
    } else if k % 2 == 0 {
        // even
        k / 2
    } else {
        // odd
        -(k + 1) / 2
    }
}

fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    let mut results = Vec::with_capacity(queries.len());
    for (l, r) in queries {
        let sum_r = prefix_sum(r);
        let sum_l_minus_1 = prefix_sum(l - 1);
        results.push(sum_r - sum_l_minus_1);
    }
    results
}